                    <div className="min-w-0 flex-1">
                      <div className="mb-2 flex flex-wrap items-baseline justify-between gap-2 text-sm">
                        <span className="cine-head truncate text-white">{film.title || "Untitled"}</span>
                        <span className="shrink-0 tabular-nums text-zinc-200">{money(film.revenue)}</span>
                      </div>
                      <div className="h-1.5 overflow-hidden rounded-full bg-white/[0.07]">
                        <motion.div
                          initial={reducedMotion ? false : { width: 0 }}
                          whileInView={{ width: `${Math.min(100, Math.max(0, Number(film.revenue || 0) / maximumRevenue * 100))}%` }}
                          viewport={{ once: true }}
                          transition={{ duration: reducedMotion ? 0 : 0.8, ease: EASE }}
                          className="h-full rounded-full bg-[#D71935]"
                        />
                      </div>
                      <p className="mt-2 text-[11px] text-zinc-500">{number(film.bookings)} bookings · {number(film.tickets)} tickets</p>
                    </div>
                  </div>
                )) : <EmptyData>No confirmed movie revenue yet.</EmptyData>}
              </div>
            </section>

            <section className={`${surface} p-5 sm:p-7`} aria-label="Booking status distribution">
              <SectionLabel index="03">Transaction mix</SectionLabel>
              <h2 className="cine-head mt-4 text-[clamp(1.45rem,2.5vw,2rem)]">Where bookings stand</h2>
              {statuses.length ? (
                <>
                  <div className="mt-8 flex h-2.5 overflow-hidden rounded-full bg-white/[0.06]">
                    {statuses.map((item, index) => (
                      <div key={`${item.status}-${index}`} title={`${item.status}: ${item.count}`}
                        style={{ width: `${statusTotal ? Number(item.count || 0) / statusTotal * 100 : 0}%`, backgroundColor: STATUS_COLORS[index % STATUS_COLORS.length] }} />
                    ))}
                  </div>
                  <div className="mt-5 space-y-2">
                    {statuses.map((item, index) => (
                      <div key={`${item.status}-${index}`} className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.07] bg-white/[0.025] px-4 py-3 text-sm">
                        <span className="flex min-w-0 items-center gap-3 text-zinc-300">
                          <span className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: STATUS_COLORS[index % STATUS_COLORS.length] }} />
                          <span className="truncate">{String(item.status || "Unknown").replace(/_/g, " ")}</span>
                        </span>
                        <span className="shrink-0 tabular-nums text-white">{number(item.count)}</span>
                      </div>
                    ))}
                  </div>
                </>
              ) : <EmptyData>No booking status data yet.</EmptyData>}
            </section>
          </div>

          <div className="mt-5 grid gap-5 xl:grid-cols-2">
            <section className={`${surface} p-5 sm:p-7`} aria-label="Low occupancy screening report">
              <SectionLabel index="04">Demand watch</SectionLabel>
              <div className="mt-4 flex flex-wrap items-end justify-between gap-2">
                <h2 className="cine-head text-[clamp(1.45rem,2.5vw,2rem)]">Low occupancy</h2>
                <span className="text-xs text-zinc-500">Next 7 days</span>
              </div>
              <p className="mt-2 text-xs text-zinc-500">{number(upcomingCount)} upcoming shows in the reporting window</p>
              <div className="mt-6 space-y-3">
                {lowOccupancy.length ? lowOccupancy.map((show, index) => {
                  const percentage = Math.min(100, Math.max(0, Number(show.occupancy || 0)));
                  return (
                    <div key={show.showId || index} className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-4">
                      <div className="flex items-start justify-between gap-4">
                        <div className="min-w-0">
                          <p className="cine-head truncate text-sm text-white">{show.movie || "Film"}</p>
                          <p className="mt-1 text-xs leading-5 text-zinc-500">
                            {show.theatre || "Cinema"} · {show.startTime
                              ? new Date(show.startTime).toLocaleString("en-IN", { timeZone: "Asia/Kolkata", day: "numeric", month: "short", hour: "numeric", minute: "2-digit" })
                              : "—"}
                          </p>
                        </div>
                        <span className="cine-head shrink-0 text-xl tabular-nums text-[#ff5874]">{percentage.toFixed(0)}%</span>
                      </div>
                      <div className="mt-4 h-1.5 overflow-hidden rounded-full bg-white/10">
                        <div className="h-full rounded-full bg-[#D71935]" style={{ width: `${percentage}%` }} />
                      </div>
                      <p className="mt-2 text-[11px] text-zinc-500">{number(show.ticketsSold)} / {number(show.capacity)} seats sold</p>
                    </div>
                  );
                }) : <EmptyData>No upcoming occupancy data yet.</EmptyData>}
              </div>
            </section>

            <section className={`${surface} p-5 sm:p-7`} aria-label="Showtime revenue report">
              <SectionLabel index="05">Screening hours</SectionLabel>
              <h2 className="cine-head mt-4 text-[clamp(1.45rem,2.5vw,2rem)]">Best-performing slots</h2>
              <p className="mt-2 text-xs text-zinc-500">Time slots ranked by confirmed revenue</p>
              <div className="mt-6 divide-y divide-white/[0.08]">
                {timeSlots.length ? timeSlots.map((slot, index) => (
                  <div key={`${slot.hour}-${index}`} className="flex items-center justify-between gap-4 py-5">
                    <div className="flex min-w-0 items-center gap-4">
                      <span className="text-lg tabular-nums text-[#ff5874]">{String(index + 1).padStart(2, "0")}</span>
                      <div className="min-w-0">
                        <p className="cine-head truncate text-sm text-white">{slot.label || `${slot.hour}:00`}</p>
                        <p className="mt-1 text-xs text-zinc-500">{number(slot.bookings)} bookings · {number(slot.tickets)} tickets</p>
                      </div>
                    </div>
                    <span className="shrink-0 text-sm font-semibold tabular-nums text-zinc-200">{money(slot.revenue)}</span>
                  </div>
                )) : <EmptyData>No showtime performance data yet.</EmptyData>}
              </div>
            </section>
          </div>
          <p className="mt-7 flex items-center gap-2 text-xs text-zinc-500">
            <BarChart3 size={15} className="text-[#ff5874]" /> Reports use current platform data, not simulated figures.
          </p>
        </>
      )}
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import axios from "axios";
import toast from "react-hot-toast";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  Activity, ArrowLeft, ArrowRight, CalendarClock, CheckCircle2,
  CircleAlert, IndianRupee, RefreshCw, Save, Search, SlidersHorizontal,
} from "lucide-react";
import { useAuth } from "../../context/AuthContext";

const API = (process.env.REACT_APP_BACKEND_URL || "").replace(/\/+$/, "");
const ENDPOINT = `${API}/api/admin/pricing`;
const EASE = [0.22, 1, 0.36, 1];
const PANEL = "rounded-[22px] border border-white/10 bg-[#111114]/90";
const INPUT = "w-full rounded-xl border border-white/10 bg-[#1a191e] px-4 py-3 text-sm text-white outline-none transition-colors focus:border-[#D71935]/70 disabled:opacity-50";

const DEFAULT_POLICY = {
  enabled: false,
  minMultiplier: 0.9,
  maxMultiplier: 1.3,
  lowOccupancyThreshold: 0.3,
  highOccupancyThreshold: 0.75,
  lowDemandDiscount: 0.05,
  highDemandSurcharge: 0.15,
  last48HoursSurcharge: 0.05,
  last12HoursSurcharge: 0.05,
  weekendSurcharge: 0.05,
  openingWeekSurcharge: 0.05,
};

const SECTIONS = [
  {
    title: "Price boundaries",
    subtitle: "The final multiplier never leaves these limits.",
    fields: [
      ["minMultiplier", "Minimum multiplier", 0.8, 1, 0.01],
      ["maxMultiplier", "Maximum multiplier", 1, 1.5, 0.01],
    ],
  },
  {
    title: "Occupancy rules",
    subtitle: "Demand is based on permanently booked seats.",
    fields: [
      ["lowOccupancyThreshold", "Low occupancy", 0, 1, 0.01],
      ["highOccupancyThreshold", "High occupancy", 0, 1, 0.01],
      ["lowDemandDiscount", "Low-demand discount", 0, 0.2, 0.01],
      ["highDemandSurcharge", "High-demand surcharge", 0, 0.3, 0.01],
    ],
  },
  {
    title: "Showtime adjustments",
    subtitle: "Additional modifiers, still subject to the price boundaries.",
    fields: [
      ["last48HoursSurcharge", "Within 48 hours", 0, 0.15, 0.01],
      ["last12HoursSurcharge", "Within 12 hours", 0, 0.15, 0.01],
      ["weekendSurcharge", "Weekend", 0, 0.15, 0.01],
      ["openingWeekSurcharge", "Release week", 0, 0.15, 0.01],
    ],
  },
];

const FIELDS = SECTIONS.flatMap((section) => section.fields);
const identifier = (show) => String(show?._id || "");
const formatNumber = (n) => Number(n || 0).toLocaleString("en-IN");

const formatDate = (value) => {
  if (!value || Number.isNaN(new Date(value).getTime())) return "Time unavailable";

  return new Intl.DateTimeFormat("en-IN", {
    timeZone: "Asia/Kolkata",
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(value));
};

const errorText = (error) =>
  error.response?.data?.message ||
  error.response?.data?.error ||
  "Pricing service unavailable.";

const normalize = (value) => ({
  ...DEFAULT_POLICY,
  ...Object.fromEntries(
    Object.keys(DEFAULT_POLICY)
      .filter((key) => value?.[key] !== undefined)
      .map((key) => [key, value[key]])
  ),
});

function validationError(policy) {
  if (!policy) return "Choose a screening first.";

  for (const [key, label, low, high] of FIELDS) {
    const raw = policy[key];
    const n = Number(raw);

    if (raw === "" || raw == null || !Number.isFinite(n) || n < low || n > high) {
      return `${label} must be between ${low} and ${high}.`;
    }
  }

  if (Number(policy.minMultiplier) > Number(policy.maxMultiplier)) {
    return "Minimum multiplier cannot exceed maximum.";
  }

  if (Number(policy.lowOccupancyThreshold) >= Number(policy.highOccupancyThreshold)) {
    return "Low occupancy must be below high occupancy.";
  }

  return "";
}

function Eyebrow({ children, index }) {
  return (
    <p className="flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[0.22em] text-[#ff526e]">
      <span className="h-px w-7 bg-[#D71935]" />
      {children}
      <span className="text-zinc-600">/ {index}</span>
    </p>
  );
}

function Metric({ label, value, icon: Icon, note }) {
  return (
    <div className={`${PANEL} p-5 transition-colors hover:border-[#D71935]/35 sm:p-6`}>
      <div className="flex items-center justify-between gap-2 text-xs text-zinc-400">
        <span>{label}</span>
        <Icon size={17} className="text-[#ff526e]" />
      </div>
      <p className="cine-head mt-4 text-3xl tabular-nums text-white">
        {formatNumber(value)}
      </p>
      <p className="mt-2 text-[11px] text-zinc-500">{note}</p>
    </div>
  );
}

export default function AdminDynamicPricing() {
  const { token } = useAuth();
  const reduced = useReducedMotion();

  const [page, setPage] = useState(1);
  const [shows, setShows] = useState([]);
  const [pagination, setPagination] = useState({ pages: 0, total: 0 });
  const [selectedId, setSelectedId] = useState("");
  const [query, setQuery] = useState("");
  const [listLoading, setListLoading] = useState(true);
  const [listError, setListError] = useState("");
  const [draft, setDraft] = useState(null);
  const [original, setOriginal] = useState(null);
  const [editorLoading, setEditorLoading] = useState(false);
  const [editorError, setEditorError] = useState("");
  const [saving, setSaving] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [notice, setNotice] = useState(false);
  const refreshController = useRef(null);

  const loadShows = useCallback(async (signal) => {
    if (!token) {
      setListError("Administrator authentication is required.");
      return false;
    }

    setListError("");

    try {
      const { data } = await axios.get(ENDPOINT, {
        headers: { Authorization: `Bearer ${token}` },
        params: { page },
        signal,
        timeout: 12000,
      });

      if (signal?.aborted) return false;

      const records = Array.isArray(data?.shows) ? data.shows : [];

      setShows(records);
      setPagination(data?.pagination || { pages: 0, total: 0 });

      setSelectedId((previous) =>
        records.some((show) => identifier(show) === previous)
          ? previous
          : identifier(records[0])
      );

      return true;
    } catch (error) {
      if (signal?.aborted || axios.isCancel(error)) return false;
      setListError(errorText(error));
      return false;
    }
  }, [token, page]);

  const loadPolicy = useCallback(async (showId, signal) => {
    if (!token || !showId) return false;

    setEditorError("");

    try {
      const { data } = await axios.get(
        `${ENDPOINT}/${encodeURIComponent(showId)}`,
        {
          headers: { Authorization: `Bearer ${token}` },
          signal,
          timeout: 12000,
        }
      );

      if (signal?.aborted) return false;

      const policy = normalize(data?.policy);
      setDraft(policy);
      setOriginal(policy);
      return true;
    } catch (error) {
      if (signal?.aborted || axios.isCancel(error)) return false;
      setEditorError(errorText(error));
      return false;
    }
  }, [token]);

  useEffect(() => {
    const controller = new AbortController();
    setListLoading(true);

    loadShows(controller.signal).finally(() => {
      if (!controller.signal.aborted) setListLoading(false);
    });

    return () => controller.abort();
  }, [loadShows]);

  useEffect(() => {
    const controller = new AbortController();

    setDraft(null);
    setOriginal(null);

    if (!selectedId) return () => controller.abort();

    setEditorLoading(true);

    loadPolicy(selectedId, controller.signal).finally(() => {
      if (!controller.signal.aborted) setEditorLoading(false);
    });

    return () => controller.abort();
  }, [loadPolicy, selectedId]);

  useEffect(() => () => refreshController.current?.abort(), []);

  useEffect(() => {
    if (!notice) return undefined;

    const timer = window.setTimeout(() => setNotice(false), 5000);
    return () => window.clearTimeout(timer);
  }, [notice]);

  const changed = Boolean(
    draft && original && JSON.stringify(draft) !== JSON.stringify(original)
  );

  const selected = shows.find((show) => identifier(show) === selectedId);

  const visibleShows = useMemo(() => {
    const term = query.toLowerCase().trim();

    return !term
      ? shows
      : shows.filter((show) =>
          [
            show.movie?.title,
            show.theatre?.name,
            show.theatre?.city,
            show.screen?.name,
            show.screen?.screenNumber,
          ].some((part) => String(part ?? "").toLowerCase().includes(term))
        );
  }, [query, shows]);

  const activeCount = shows.filter((show) => show.dynamicPricing?.enabled).length;

  const confirmDiscard = () =>
    !changed || window.confirm("Discard the unsaved pricing changes?");

  function selectShow(id) {
    if (!saving && !refreshing && confirmDiscard()) setSelectedId(id);
  }

  function changePage(next) {
    if (saving || refreshing || listLoading || !confirmDiscard()) return;
    setPage(next);
  }

  async function refresh() {
    if (
      saving ||
      refreshing ||
      listLoading ||
      editorLoading ||
      !confirmDiscard()
    ) return;

    const controller = new AbortController();
    refreshController.current = controller;

    setNotice(false);
    setRefreshing(true);

    try {
      const [listOk, policyOk] = await Promise.all([
        loadShows(controller.signal),
        selectedId
          ? loadPolicy(selectedId, controller.signal)
          : Promise.resolve(true),
        new Promise((resolve) => window.setTimeout(resolve, 650)),
      ]);

      if (!controller.signal.aborted && listOk && policyOk) {
        setNotice(true);
      }
    } finally {
      if (!controller.signal.aborted) setRefreshing(false);

      if (refreshController.current === controller) {
        refreshController.current = null;
      }
    }
  }

  async function save(event) {
    event.preventDefault();

    if (saving || refreshing || editorLoading || !selectedId || !draft) return;

    const invalid = validationError(draft);

    if (invalid) {
      toast.error(invalid);
      return;
    }

    if (
      draft.enabled &&
      !original?.enabled &&
      !window.confirm(
        "Enable dynamic pricing for this show? New payment requests may use adjusted ticket prices."
      )
    ) return;

    const payload = { enabled: Boolean(draft.enabled) };

    for (const [key] of FIELDS) {
      payload[key] = Number(draft[key]);
    }

    setSaving(true);

    try {
      const { data } = await axios.put(
        `${ENDPOINT}/${encodeURIComponent(selectedId)}`,
        payload,
        {
          headers: { Authorization: `Bearer ${token}` },
          timeout: 12000,
        }
      );

      const saved = normalize(data?.policy || payload);

      setDraft(saved);
      setOriginal(saved);

      setShows((previous) =>
        previous.map((show) =>
          identifier(show) === selectedId
            ? { ...show, dynamicPricing: saved }
            : show
        )
      );

      toast.success(data?.message || "Pricing policy saved.");
    } catch (error) {
      toast.error(errorText(error));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="mx-auto max-w-[1460px] pb-16 text-white">
      <header className="flex flex-wrap items-end justify-between gap-6 border-b border-white/10 pb-7">
        <div className="min-w-0">
          <Eyebrow index="10">Revenue management</Eyebrow>

          <h1 className="cine-display mt-5 text-[clamp(2.2rem,3.8vw,3.8rem)] leading-[1.14]">
            Intelligent <span className="text-[#ff4562]">pricing.</span>
          </h1>

          <p className="mt-4 max-w-[590px] text-sm leading-7 text-zinc-400">
            Fine-tune demand-based pricing per screening. Policies remain
            inactive until explicitly enabled and saved.
          </p>
        </div>

        <div className="flex flex-col items-start gap-2 sm:items-end">
          <button
            type="button"
            aria-busy={refreshing}
            disabled={refreshing || saving || listLoading || editorLoading}
            onClick={refresh}
            className="inline-flex min-h-[44px] items-center gap-2.5 rounded-full border border-white/20 bg-white/[0.035] px-5 py-3 text-xs font-semibold text-zinc-200 transition-colors hover:border-[#D71935]/60 hover:bg-[#D71935]/10 disabled:opacity-50"
          >
            <motion.span
              className="inline-flex text-[#ff526e]"
              animate={refreshing && !reduced ? { rotate: 360 } : { rotate: 0 }}
              transition={
                refreshing && !reduced
                  ? { repeat: Infinity, duration: 1.15, ease: "linear" }
                  : { duration: 0.2 }
              }
            >
              <RefreshCw size={16} />
            </motion.span>
            {refreshing ? "Refreshing..." : "Refresh pricing"}
          </button>

          <div className="min-h-[20px]" aria-live="polite">
            <AnimatePresence>
              {notice && (
                <motion.p
                  key="success"
                  role="status"
                  initial={reduced ? false : { opacity: 0, y: -5 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                  className="inline-flex items-center gap-2 text-xs text-emerald-300"
                >
                  <CheckCircle2 size={15} />
                  Pricing data updated
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>
      </header>

      <section aria-label="Pricing overview" className="mt-7 grid gap-4 sm:grid-cols-3">
        <Metric
          label="Upcoming screenings"
          value={pagination.total}
          note="Across all result pages"
          icon={CalendarClock}
        />
        <Metric
          label="On this page"
          value={shows.length}
          note="Up to 30 screenings"
          icon={Activity}
        />
        <Metric
          label="Dynamic pricing active"
          value={activeCount}
          note="Count on this page only"
          icon={IndianRupee}
        />
      </section>

      <div className="mt-7 grid items-start gap-5 xl:grid-cols-[minmax(270px,.85fr)_minmax(0,1.5fr)]">
        <section className={`${PANEL} min-w-0 overflow-hidden`} aria-label="Upcoming shows">
          <div className="border-b border-white/10 p-5 sm:p-6">
            <Eyebrow index="01">Choose a screening</Eyebrow>
            <h2 className="cine-head mt-4 text-2xl">Upcoming shows</h2>
            <p className="mt-2 text-xs text-zinc-500">
              Choose a screening to adjust its individual policy.
            </p>

            <div className="relative mt-5">
              <Search
                size={16}
                className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500"
              />
              <input
                type="search"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                aria-label="Filter shows on this page"
                placeholder="Search within this page"
                className={`${INPUT} pl-11`}
              />
            </div>

            {listError && (
              <p role="alert" className="mt-4 text-xs leading-6 text-rose-300">
                {listError}
              </p>
            )}
          </div>

          <div className="max-h-[620px] space-y-2 overflow-y-auto p-3">
            {listLoading && (
              <p role="status" className="p-5 text-sm text-zinc-400">
                Loading upcoming shows...
              </p>
            )}

            {!listLoading && !visibleShows.length && (
              <p className="p-5 text-sm text-zinc-500">
                No matching upcoming screenings.
              </p>
            )}

            {!listLoading && visibleShows.map((show, index) => {
              const active = identifier(show) === selectedId;

              return (
                <button
                  key={identifier(show)}
                  type="button"
                  disabled={saving || refreshing}
                  aria-pressed={active}
                  onClick={() => selectShow(identifier(show))}
                  className={`group flex w-full items-start gap-3 rounded-xl border p-4 text-left transition-colors disabled:opacity-60 ${
                    active
                      ? "border-[#D71935]/60 bg-[#D71935]/10"
                      : "border-white/[0.07] bg-[#19191d] hover:border-white/25"
                  }`}
                >
                  <span className="mt-0.5 text-[10px] tabular-nums text-[#ff526e]">
                    {String(index + 1).padStart(2, "0")}
                  </span>

                  <span className="min-w-0 flex-1">
                    <span className="cine-head block break-words text-[15px] text-white">
                      {show.movie?.title || "Untitled film"}
                    </span>
                    <span className="mt-2 block text-xs text-zinc-400">
                      {formatDate(show.startTime)}
                    </span>
                    <span className="mt-1 block text-xs leading-5 text-zinc-500">
                      {[show.theatre?.name, show.screen?.name]
                        .filter(Boolean).join(" · ") || "Location unavailable"}
                    </span>
                  </span>

                  <span className={`shrink-0 rounded-full border px-2.5 py-1 text-[10px] font-semibold ${
                    show.dynamicPricing?.enabled
                      ? "border-[#D71935]/50 bg-[#D71935]/15 text-[#ff8295]"
                      : "border-white/10 text-zinc-400"
                  }`}>
                    {show.dynamicPricing?.enabled ? "Dynamic" : "Fixed"}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="flex items-center justify-between gap-3 border-t border-white/10 p-4 text-xs text-zinc-400 sm:px-6">
            <span>
              Page {page} / {Math.max(1, Number(pagination.pages) || 1)}
            </span>
            <div className="flex gap-2">
              <button
                type="button"
                aria-label="Previous page"
                disabled={page <= 1 || listLoading || refreshing || saving}
                onClick={() => changePage(page - 1)}
                className="rounded-full border border-white/15 p-2.5 hover:bg-white/10 disabled:opacity-30"
              >
                <ArrowLeft size={16} />
              </button>

              <button
                type="button"
                aria-label="Next page"
                disabled={page >= Number(pagination.pages || 0) || listLoading || refreshing || saving}
                onClick={() => changePage(page + 1)}
                className="rounded-full border border-white/15 p-2.5 hover:bg-white/10 disabled:opacity-30"
              >
                <ArrowRight size={16} />
              </button>
            </div>
          </div>
        </section>

        <motion.section
          key={selectedId || "empty"}
          initial={reduced ? false : { opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.35, ease: EASE }}
          className={`${PANEL} min-w-0 overflow-hidden p-5 sm:p-7`}
          aria-label="Pricing policy editor"
        >
          {!selectedId ? (
            <p className="py-20 text-center text-sm text-zinc-400">
              Select an upcoming show to configure its pricing.
            </p>
          ) : editorLoading || !draft ? (
            <div className="py-20 text-center text-sm text-zinc-400" role="status">
              {editorError ? (
                <p role="alert" className="text-rose-300">{editorError}</p>
              ) : "Loading pricing policy..."}
            </div>
          ) : (
            <form onSubmit={save}>
              <div className="flex flex-wrap items-start justify-between gap-5 border-b border-white/10 pb-6">
                <div className="min-w-0">
                  <Eyebrow index="02">Policy editor</Eyebrow>
                  <h2 className="cine-head mt-4 break-words text-2xl">
                    {selected?.movie?.title || "Selected screening"}
                  </h2>
                  <p className="mt-2 text-xs text-zinc-400">
                    {formatDate(selected?.startTime)}
                  </p>
                </div>

                <label className="flex cursor-pointer items-center gap-3 rounded-xl border border-white/15 bg-white/[0.04] px-4 py-3">
                  <span className="text-xs font-semibold text-zinc-200">
                    Enable policy
                  </span>
                  <input
                    type="checkbox"
                    checked={Boolean(draft.enabled)}
                    onChange={(event) => setDraft((previous) => ({
                      ...previous,
                      enabled: event.target.checked,
                    }))}
                    className="h-5 w-5 accent-[#D71935]"
                  />
                </label>
              </div>

              <div className="mt-6 flex items-start gap-3 rounded-xl border border-[#D71935]/25 bg-[#D71935]/[0.07] p-4">
                <CircleAlert
                  size={18}
                  className="mt-0.5 shrink-0 text-[#ff8295]"
                />
                <p className="text-xs leading-6 text-zinc-300">
                  {draft.enabled
                    ? "Saving this enabled policy affects new payment requests. PaymentIntents created earlier retain their existing price."
                    : "Fixed prices remain active. You can save these parameters without enabling dynamic pricing."}
                </p>
              </div>

              {SECTIONS.map((section, index) => (
                <fieldset
                  key={section.title}
                  className="mt-7 border-t border-white/10 pt-6"
                >
                  <legend className="sr-only">{section.title}</legend>
                  <p className="text-[10px] font-semibold uppercase tracking-[0.2em] text-[#ff526e]">
                    {String(index + 1).padStart(2, "0")} / Rules
                  </p>
                  <h3 className="cine-head mt-3 text-xl text-white">
                    {section.title}
                  </h3>
                  <p className="mt-2 text-xs leading-6 text-zinc-500">
                    {section.subtitle}
                  </p>

                  <div className="mt-5 grid gap-4 sm:grid-cols-2">
                    {section.fields.map(([key, label, low, high, step]) => (
                      <label
                        key={key}
                        className="block rounded-xl border border-white/[0.07] bg-white/[0.025] p-4"
                      >
                        <span className="block text-xs text-zinc-300">
                          {label}
                        </span>
                        <input
                          type="number"
                          inputMode="decimal"
                          required
                          value={draft[key]}
                          min={low}
                          max={high}
                          step={step}
                          onChange={(event) => setDraft((previous) => ({
                            ...previous,
                            [key]: event.target.value,
                          }))}
                          className={`${INPUT} mt-3`}
                        />
                        <span className="mt-2 block text-[11px] text-zinc-500">
                          {key.includes("Multiplier")
                            ? `${low}×–${high}× base`
                            : `${Math.round(low * 100)}%–${Math.round(high * 100)}%`}
                        </span>
                      </label>
                    ))}
                  </div>
                </fieldset>
              ))}

              <div className="mt-8 flex flex-wrap items-center justify-between gap-4 border-t border-white/10 pt-6">
                <p className={`text-xs ${changed ? "text-amber-200" : "text-zinc-500"}`}>
                  {changed ? "Unsaved changes" : "All changes saved"}
                </p>
                <button
                  type="submit"
                  disabled={!changed || saving || refreshing}
                  className="inline-flex min-h-[44px] items-center gap-2 rounded-full bg-[#D71935] px-6 py-3 text-sm font-semibold text-white transition-colors hover:bg-[#ed304d] disabled:cursor-not-allowed disabled:opacity-45"
                >
                  {saving
                    ? <RefreshCw size={16} className={reduced ? "" : "animate-spin"} />
                    : <Save size={16} />}
                  {saving ? "Saving..." : "Save policy"}
                </button>
              </div>
            </form>
          )}
        </motion.section>
      </div>
    </div>
  );
}

import React, {
  useEffect,
  useMemo,
  useState,
} from "react";

import axios from "axios";
import toast from "react-hot-toast";
import { motion } from "framer-motion";

import {
  Building2,
  CheckCircle2,
  Loader2,
  Mail,
  RefreshCw,
  Shield,
  User,
  UserRoundCog,
  Users,
  XCircle,
} from "lucide-react";

import {
  AdminHeader,
  AdminSearch,
  AdminStat,
  Empty,
  Loading,
  Pager,
  Pill,
  Segmented,
  TableCard,
  td,
  th,
} from "../../components/ui/admin";

import { useAuth } from "../../context/AuthContext";

const API_URL = (
  process.env.REACT_APP_BACKEND_URL || ""
).replace(/\/+$/, "");

const PAGE_SIZE = 20;

const PARTNER_API =
  `${API_URL}/api/admin/partner-assignments`;

function getError(error, fallback) {
  return (
    error.response?.data?.message ||
    error.response?.data?.error ||
    fallback
  );
}

function partnerIdOf(value) {
  if (!value) return "";

  return String(
    typeof value === "object"
      ? value._id || ""
      : value
  );
}

const AdminUsers = () => {
  const {
    token,
    user: currentUser,
  } = useAuth();

  // =====================================================
  // EXISTING USER MANAGEMENT
  // =====================================================

  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] =
    useState("all");
  const [page, setPage] = useState(1);

  const [pagination, setPagination] =
    useState({
      page: 1,
      pages: 1,
      total: 0,
    });

  const [changingRole, setChangingRole] =
    useState(null);

  const [grantingPartner, setGrantingPartner] =
    useState(null);

  // =====================================================
  // FEATURE 7 — PARTNER ASSIGNMENTS
  // =====================================================

  const [partners, setPartners] = useState([]);
  const [theatres, setTheatres] = useState([]);

  const [
    selectedAssignments,
    setSelectedAssignments,
  ] = useState({});

  const [
    assignmentsLoading,
    setAssignmentsLoading,
  ] = useState(true);

  const [
    assignmentsError,
    setAssignmentsError,
  ] = useState("");

  const [
    savingTheatre,
    setSavingTheatre,
  ] = useState(null);

  const [
    assignmentRevision,
    setAssignmentRevision,
  ] = useState(0);

  const currentUserId = String(
    currentUser?._id ||
    currentUser?.id ||
    ""
  );

  // =====================================================
  // LOAD USERS
  // =====================================================

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return undefined;
    }

    const controller = new AbortController();

    const timer = setTimeout(async () => {
      setLoading(true);

      try {
        const params = {
          page,
          limit: PAGE_SIZE,
        };

        if (search.trim()) {
          params.search = search.trim();
        }

        if (roleFilter !== "all") {
          params.role = roleFilter;
        }

        const { data } = await axios.get(
          `${API_URL}/api/admin/users`,
          {
            params,
            signal: controller.signal,
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        if (controller.signal.aborted) return;

        setUsers(data.users || []);

        setPagination(
          data.pagination || {
            page: 1,
            pages: 1,
            total: 0,
          }
        );
      } catch (error) {
        if (controller.signal.aborted) return;

        toast.error(
          getError(
            error,
            "Could not load users."
          )
        );
      } finally {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      }
    }, 300);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [
    search,
    roleFilter,
    page,
    token,
  ]);

  // =====================================================
  // LOAD PARTNERS AND THEATRE OWNERSHIP
  // =====================================================

  useEffect(() => {
    if (!token) {
      setAssignmentsLoading(false);
      return undefined;
    }

    const controller = new AbortController();

    const config = {
      headers: {
        Authorization: `Bearer ${token}`,
      },
      signal: controller.signal,
    };

    setAssignmentsLoading(true);
    setAssignmentsError("");

    Promise.all([
      axios.get(
        `${PARTNER_API}/partners`,
        config
      ),
      axios.get(
        `${PARTNER_API}/theatres`,
        config
      ),
    ])
      .then(([partnerResponse, theatreResponse]) => {
        if (controller.signal.aborted) return;

        const partnerList =
          partnerResponse.data.partners || [];

        const theatreList =
          theatreResponse.data.theatres || [];

        setPartners(partnerList);
        setTheatres(theatreList);

        const assignments = {};

        theatreList.forEach((theatre) => {
          assignments[theatre._id] =
            partnerIdOf(theatre.partner);
        });

        setSelectedAssignments(assignments);
      })
      .catch((error) => {
        if (controller.signal.aborted) return;

        setAssignmentsError(
          getError(
            error,
            "Could not load cinema partner assignments."
          )
        );
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setAssignmentsLoading(false);
        }
      });

    return () => controller.abort();
  }, [token, assignmentRevision]);

  // =====================================================
  // SUMMARY
  // =====================================================

  const stats = useMemo(
    () => ({
      admins: users.filter(
        (item) => item.role === "admin"
      ).length,

      verified: users.filter(
        (item) => item.emailVerified !== false
      ).length,

      google: users.filter(
        (item) => Boolean(item.googleId)
      ).length,
    }),
    [users]
  );

  const updateSearch = (value) => {
    setSearch(value);
    setPage(1);
  };

  const updateRoleFilter = (value) => {
    setRoleFilter(value);
    setPage(1);
  };

  // =====================================================
  // EXISTING ADMIN ROLE MANAGEMENT
  // =====================================================

  const changeRole = async (
    userId,
    newRole
  ) => {
    const targetUser = users.find(
      (item) =>
        String(item._id) === String(userId)
    );

    if (
      !targetUser ||
      changingRole ||
      grantingPartner
    ) {
      return;
    }

    // Partner privileges must not be changed
    // through the general admin-role toggle.
    if (
      !["user", "admin"].includes(
        targetUser.role
      )
    ) {
      toast.error(
        "Manage partner accounts through partner assignments."
      );

      return;
    }

    if (
      String(userId) === currentUserId
    ) {
      toast.error(
        "You cannot change your own admin role."
      );
      return;
    }

    const confirmed = window.confirm(
      newRole === "admin"
        ? `Give admin access to ${targetUser.name}?`
        : `Remove admin access from ${targetUser.name}?`
    );

    if (!confirmed) return;

    setChangingRole(userId);

    try {
      const { data } = await axios.patch(
        `${API_URL}/api/admin/users/${userId}/role`,
        {
          role: newRole,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setUsers((current) =>
        current.map((item) =>
          String(item._id) === String(userId)
            ? data.user || {
                ...item,
                role: newRole,
              }
            : item
        )
      );

      toast.success(
        newRole === "admin"
          ? "Admin access granted."
          : "Admin access removed."
      );
    } catch (error) {
      toast.error(
        getError(
          error,
          "Could not update user role."
        )
      );
    } finally {
      setChangingRole(null);
    }
  };

  // =====================================================
  // GRANT PARTNER ROLE
  // =====================================================

  const grantPartner = async (targetUser) => {
    if (
      !targetUser ||
      targetUser.role !== "user" ||
      targetUser.emailVerified === false ||
      changingRole ||
      grantingPartner
    ) {
      return;
    }

    if (
      !window.confirm(
        `Grant cinema partner access to ${targetUser.name}?`
      )
    ) {
      return;
    }

    setGrantingPartner(targetUser._id);

    try {
      const { data } = await axios.patch(
        `${PARTNER_API}/users/${targetUser._id}`,
        {},
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (!data.success) {
        throw new Error(
          "Partner access was not confirmed."
        );
      }

      setUsers((current) =>
        current.map((item) =>
          item._id === targetUser._id
            ? {
                ...item,
                role: "partner",
              }
            : item
        )
      );

      setAssignmentRevision(
        (current) => current + 1
      );

      toast.success(
        "Cinema partner access granted."
      );
    } catch (error) {
      toast.error(
        getError(
          error,
          "Could not grant partner access."
        )
      );
    } finally {
      setGrantingPartner(null);
    }
  };

  // =====================================================
  // ASSIGN / UNASSIGN THEATRE
  // =====================================================

  const saveAssignment = async (theatre) => {
    if (savingTheatre) return;

    const partnerId =
      selectedAssignments[theatre._id] || "";

    const oldPartnerId =
      partnerIdOf(theatre.partner);

    if (partnerId === oldPartnerId) {
      return;
    }

    const partner = partners.find(
      (item) => item._id === partnerId
    );

    const confirmed = window.confirm(
      partnerId
        ? `Assign ${theatre.name} to ${partner?.name || "this partner"}?`
        : `Remove the current partner from ${theatre.name}?`
    );

    if (!confirmed) return;

    setSavingTheatre(theatre._id);

    try {
      const { data } = await axios.patch(
        `${PARTNER_API}/theatres/${theatre._id}`,
        {
          partnerId: partnerId || null,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (!data.success) {
        throw new Error(
          "Theatre assignment was not confirmed."
        );
      }

      setAssignmentRevision(
        (current) => current + 1
      );

      toast.success(
        partnerId
          ? "Cinema partner assigned."
          : "Cinema partner assignment removed."
      );
    } catch (error) {
      toast.error(
        getError(
          error,
          "Could not update theatre assignment."
        )
      );
    } finally {
      setSavingTheatre(null);
    }
  };

  // =====================================================
  // PAGE
  // =====================================================

  return (
    <div>
      <AdminHeader
        kicker="Accounts"
        title="Users."
        subtitle="Manage customer accounts, administrator access and cinema partnerships."
      />

      {/* ACCOUNT STATISTICS */}

      <div className="mt-10 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <AdminStat
          title="Total users"
          value={pagination.total || 0}
          icon={Users}
        />

        <AdminStat
          title="Admins on page"
          value={stats.admins}
          icon={Shield}
          delay={0.05}
        />

        <AdminStat
          title="Verified on page"
          value={stats.verified}
          icon={CheckCircle2}
          delay={0.1}
        />

        <AdminStat
          title="Cinema partners"
          value={partners.length}
          icon={Building2}
          delay={0.15}
        />
      </div>

      {/* ACCOUNT SEARCH AND FILTER */}

      <div className="mt-10 flex flex-col gap-4 lg:flex-row lg:items-center">
        <AdminSearch
          value={search}
          onChange={(event) =>
            updateSearch(event.target.value)
          }
          placeholder="Search by name or email"
          className="flex-1"
        />

        <Segmented
          label="Role"
          value={roleFilter}
          onChange={updateRoleFilter}
          options={[
            ["all", "All roles"],
            ["user", "Users"],
            ["admin", "Admins"],
          ]}
        />
      </div>

      {/* EXISTING USERS TABLE */}

      <div className="mt-8">
        {loading ? (
          <Loading label="Loading users" />
        ) : users.length === 0 ? (
          <Empty
            icon={Users}
            title="No users found"
            body="Try a different search or role."
          />
        ) : (
          <TableCard>
            <table className="w-full min-w-[1000px]">
              <thead className="border-b border-white/10 bg-white/[0.02]">
                <tr>
                  <th className={th}>User</th>
                  <th className={th}>Verification</th>
                  <th className={th}>Login method</th>
                  <th className={th}>Joined</th>
                  <th className={th}>Role</th>
                  <th className={`${th} text-right`}>
                    Access
                  </th>
                </tr>
              </thead>

              <tbody>
                {users.map((item, index) => {
                  const isCurrent =
                    String(item._id) === currentUserId;

                  const isAdmin =
                    item.role === "admin";

                  const isPartner =
                    item.role === "partner";

                  const canGrantPartner =
                    item.role === "user" &&
                    item.emailVerified !== false &&
                    !isCurrent;

                  const joined = item.createdAt
                    ? new Intl.DateTimeFormat(
                        "en-IN",
                        {
                          dateStyle: "medium",
                        }
                      ).format(new Date(item.createdAt))
                    : "—";

                  return (
                    <motion.tr
                      key={item._id}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{
                        delay: Math.min(
                          index * 0.02,
                          0.25
                        ),
                      }}
                      className="border-t border-white/5 transition-colors hover:bg-white/[0.03]"
                    >
                      <td className={td}>
                        <div className="flex items-center gap-4">
                          <span
                            className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-full border ${
                              isAdmin
                                ? "border-crimson/40 bg-crimson/10"
                                : "border-white/10 bg-white/[0.04]"
                            }`}
                          >
                            {isAdmin ? (
                              <Shield className="h-5 w-5 text-crimson" />
                            ) : isPartner ? (
                              <Building2 className="h-5 w-5 text-[#e45b73]" />
                            ) : (
                              <User className="h-5 w-5 text-zinc-500" />
                            )}
                          </span>

                          <div className="min-w-0">
                            <div className="flex items-center gap-2">
                              <p className="truncate font-medium text-bone">
                                {item.name}
                              </p>

                              {isCurrent && (
                                <Pill tone="crimson">
                                  You
                                </Pill>
                              )}
                            </div>

                            <p className="mt-0.5 truncate text-sm text-zinc-500">
                              {item.email}
                            </p>
                          </div>
                        </div>
                      </td>

                      <td className={td}>
                        {item.emailVerified !== false ? (
                          <Pill tone="good">
                            <CheckCircle2 className="h-3.5 w-3.5" />
                            Verified
                          </Pill>
                        ) : (
                          <Pill tone="warn">
                            <XCircle className="h-3.5 w-3.5" />
                            Pending
                          </Pill>
                        )}
                      </td>

                      <td className={td}>
                        <Pill tone={item.googleId ? "info" : "mute"}>
                          <Mail className="h-3.5 w-3.5" />
                          {item.googleId
                            ? "Google + email"
                            : "Email"}
                        </Pill>
                      </td>

                      <td className={`${td} text-sm text-zinc-400`}>
                        {joined}
                      </td>

                      <td className={td}>
                        <Pill
                          tone={
                            isAdmin
                              ? "crimson"
                              : isPartner
                                ? "info"
                                : "mute"
                          }
                        >
                          {isAdmin
                            ? "Admin"
                            : isPartner
                              ? "Partner"
                              : "User"}
                        </Pill>
                      </td>

                      <td className={`${td} text-right`}>
                        {isCurrent ? (
                          <span className="text-xs text-zinc-600">
                            Protected
                          </span>
                        ) : isPartner ? (
                          <span className="text-xs text-zinc-500">
                            Cinema partner
                          </span>
                        ) : (
                          <div className="flex flex-wrap justify-end gap-2">
                            {canGrantPartner && (
                              <button
                                type="button"
                                disabled={Boolean(
                                  changingRole ||
                                  grantingPartner
                                )}
                                onClick={() =>
                                  grantPartner(item)
                                }
                                className="rounded-full border border-[#D71935]/40 px-4 py-2 text-xs font-semibold text-[#f19cad] transition hover:bg-[#D71935]/10 disabled:opacity-40"
                              >
                                {grantingPartner === item._id
                                  ? "Granting..."
                                  : "Make partner"}
                              </button>
                            )}

                            <button
                              type="button"
                              disabled={Boolean(
                                changingRole ||
                                grantingPartner
                              )}
                              onClick={() =>
                                changeRole(
                                  item._id,
                                  isAdmin
                                    ? "user"
                                    : "admin"
                                )
                              }
                              className="rounded-full border border-white/15 px-4 py-2 text-xs font-semibold text-zinc-300 transition hover:border-white/40 hover:text-white disabled:opacity-40"
                            >
                              {changingRole === item._id
                                ? "Updating..."
                                : isAdmin
                                  ? "Remove admin"
                                  : "Make admin"}
                            </button>
                          </div>
                        )}
                      </td>
                    </motion.tr>
                  );
                })}
              </tbody>
            </table>
          </TableCard>
        )}
      </div>

      {!loading && pagination.pages > 1 && (
        <div className="mt-6">
          <Pager
            page={pagination.page}
            pages={pagination.pages}
            onPrev={() =>
              setPage((current) =>
                Math.max(1, current - 1)
              )
            }
            onNext={() =>
              setPage((current) =>
                Math.min(
                  pagination.pages,
                  current + 1
                )
              )
            }
          />
        </div>
      )}

      {/* ============================================= */}
      {/* FEATURE 7 — CINEMA PARTNER ASSIGNMENTS */}
      {/* ============================================= */}

      <section className="mt-16 border-t border-white/10 pt-12">
        <div className="flex flex-wrap items-start justify-between gap-5">
          <div>
            <p className="text-[11px] font-semibold uppercase tracking-[0.22em] text-[#ee647b]">
              Cinema network / Access
            </p>

            <h2 className="mt-4 text-3xl font-semibold tracking-[-0.055em] text-white sm:text-4xl">
              Partner assignments.
            </h2>

            <p className="mt-4 max-w-2xl text-sm leading-7 text-zinc-400">
              Assign verified cinema partner accounts to
              individual theatres. Each partner can access
              only their assigned locations.
            </p>
          </div>

          <button
            type="button"
            onClick={() =>
              setAssignmentRevision(
                (current) => current + 1
              )
            }
            disabled={
              assignmentsLoading ||
              Boolean(savingTheatre)
            }
            className="inline-flex items-center gap-2 rounded-full border border-white/15 px-5 py-3 text-sm text-white transition hover:border-[#D71935]/60 disabled:opacity-40"
          >
            <RefreshCw size={15} />
            Refresh assignments
          </button>
        </div>

        {assignmentsError && (
          <div
            role="alert"
            className="mt-7 rounded-xl border border-red-500/25 bg-red-500/10 p-5 text-sm text-red-200"
          >
            {assignmentsError}
          </div>
        )}

        {assignmentsLoading ? (
          <div className="mt-8 flex items-center gap-3 text-sm text-zinc-400">
            <Loader2
              size={18}
              className="animate-spin text-[#D71935]"
            />
            Loading cinema assignments...
          </div>
        ) : theatres.length === 0 ? (
          <div className="mt-8 rounded-2xl border border-white/10 bg-[#121215] p-8 text-center">
            <Building2 className="mx-auto h-8 w-8 text-zinc-500" />

            <p className="mt-4 text-sm text-zinc-400">
              {assignmentsError
                ? "Cinema assignments are unavailable."
                : "No theatres are available for assignment."}
            </p>
          </div>
        ) : (
          <div className="mt-8 overflow-hidden rounded-[24px] border border-white/10 bg-[#121215]">
            <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 px-6 py-5">
              <p className="text-sm font-semibold text-white">
                Theatre ownership
              </p>

              <p className="text-xs text-zinc-500">
                {theatres.length} cinemas · {partners.length} partners
              </p>
            </div>

            <div className="divide-y divide-white/[0.07]">
              {theatres.map((theatre) => {
                const currentPartnerId =
                  partnerIdOf(theatre.partner);

                const chosenId =
                  selectedAssignments[theatre._id] || "";

                const changed =
                  chosenId !== currentPartnerId;

                const busy =
                  savingTheatre === theatre._id;

                return (
                  <div
                    key={theatre._id}
                    className="grid items-center gap-5 px-6 py-5 xl:grid-cols-[minmax(0,1fr)_minmax(230px,340px)_auto]"
                  >
                    <div className="min-w-0">
                      <p className="truncate text-sm font-semibold text-white">
                        {theatre.name}
                      </p>

                      <p className="mt-1.5 text-xs text-zinc-500">
                        {theatre.city || "Location unavailable"}
                        {!theatre.isActive && " · Inactive"}
                      </p>

                      <p className="mt-2 text-xs text-zinc-400">
                        {theatre.partner?.name
                          ? `Current partner: ${theatre.partner.name}`
                          : "Currently unassigned"}
                      </p>
                    </div>

                    <label className="block">
                      <span className="mb-2 block text-[11px] font-medium text-zinc-500">
                        Assigned partner
                      </span>

                      <select
                        value={chosenId}
                        disabled={
                          Boolean(savingTheatre) ||
                          assignmentsLoading
                        }
                        onChange={(event) =>
                          setSelectedAssignments(
                            (current) => ({
                              ...current,
                              [theatre._id]:
                                event.target.value,
                            })
                          )
                        }
                        className="w-full rounded-xl border border-white/10 bg-[#202025] px-4 py-3 text-sm text-white outline-none transition focus:border-[#D71935] disabled:opacity-50"
                      >
                        <option value="">
                          Unassigned
                        </option>

                        {partners.map((partner) => (
                          <option
                            key={partner._id}
                            value={partner._id}
                          >
                            {partner.name} — {partner.email}
                          </option>
                        ))}
                      </select>
                    </label>

                    <button
                      type="button"
                      onClick={() =>
                        saveAssignment(theatre)
                      }
                      disabled={
                        !changed ||
                        Boolean(savingTheatre)
                      }
                      className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full bg-[#D71935] px-6 py-3 text-xs font-semibold text-white transition hover:bg-[#e22b47] disabled:cursor-not-allowed disabled:opacity-35 xl:self-end"
                    >
                      {busy && (
                        <Loader2
                          size={14}
                          className="animate-spin"
                        />
                      )}

                      {busy
                        ? "Saving..."
                        : "Save assignment"}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        <p className="mt-5 text-xs leading-6 text-zinc-500">
          To add a new partner, find a verified customer
          account above and select "Make partner".
          Theatre reassignment takes effect through
          backend ownership checks.
        </p>
      </section>
    </div>
  );
};

export default AdminUsers;

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, DollarSign } from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';
import { useAuth } from '../../context/AuthContext';

const API_URL = process.env.REACT_APP_BACKEND_URL;

const ListBookings = () => {
  const { token } = useAuth();
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/admin/bookings`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setBookings(response.data.bookings);
    } catch (error) {
      console.error('Error fetching bookings:', error);
      toast.error('Failed to load bookings');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div data-testid="list-bookings-page">
      <h1 className="text-4xl font-bold mb-8" data-testid="list-bookings-title">All Bookings</h1>

      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="text-zinc-400">Loading...</div>
        </div>
      ) : bookings.length === 0 ? (
        <div className="text-center py-16 text-zinc-400" data-testid="no-bookings">
          No bookings yet
        </div>
      ) : (
        <div className="overflow-x-auto" data-testid="bookings-table">
          <table className="w-full">
            <thead>
              <tr className="border-b border-white/10">
                <th className="text-left py-4 px-4">User Name</th>
                <th className="text-left py-4 px-4">Email</th>
                <th className="text-left py-4 px-4">Movie Name</th>
                <th className="text-left py-4 px-4">Show Time</th>
                <th className="text-left py-4 px-4">Seats</th>
                <th className="text-left py-4 px-4">Total Amount</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking, idx) => (
                <motion.tr
                  key={booking._id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  className="border-b border-white/5 hover:bg-white/5"
                  data-testid={`booking-row-${idx}`}
                >
                  <td className="py-4 px-4">
                    <div className="font-semibold">{booking.user.name}</div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="text-sm text-zinc-400">{booking.user.email}</div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="font-semibold">{booking.movie.title}</div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="flex items-center space-x-2 text-sm">
                      <Calendar className="h-4 w-4 text-red-500" strokeWidth={1.5} />
                      <span>{new Date(booking.show.date).toLocaleDateString()}</span>
                      <Clock className="h-4 w-4 text-red-500 ml-2" strokeWidth={1.5} />
                      <span>{booking.show.time}</span>
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="flex flex-wrap gap-1">
                      {booking.seats.map((seat) => (
                        <span key={seat} className="px-2 py-1 bg-red-600/20 text-red-500 rounded text-xs font-semibold">
                          {seat}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="font-bold text-green-500 flex items-center">
                      <DollarSign className="h-4 w-4" strokeWidth={1.5} />
                      {booking.totalAmount.toFixed(2)}
                    </div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default ListBookings;

import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, DollarSign } from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';
import { useAuth } from '../../context/AuthContext';

const API_URL = process.env.REACT_APP_BACKEND_URL;

const ListShows = () => {
  const { token } = useAuth();
  const [shows, setShows] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchShows();
  }, []);

  const fetchShows = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/admin/shows`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setShows(response.data.shows);
    } catch (error) {
      console.error('Error fetching shows:', error);
      toast.error('Failed to load shows');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div data-testid="list-shows-page">
      <h1 className="text-4xl font-bold mb-8" data-testid="list-shows-title">All Shows</h1>

      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="text-zinc-400">Loading...</div>
        </div>
      ) : shows.length === 0 ? (
        <div className="text-center py-16 text-zinc-400" data-testid="no-shows">
          No shows available
        </div>
      ) : (
        <div className="overflow-x-auto" data-testid="shows-table">
          <table className="w-full">
            <thead>
              <tr className="border-b border-white/10">
                <th className="text-left py-4 px-4">Movie Name</th>
                <th className="text-left py-4 px-4">Show Time</th>
                <th className="text-left py-4 px-4">Price</th>
                <th className="text-left py-4 px-4">Booked Seats</th>
                <th className="text-left py-4 px-4">Total Bookings</th>
                <th className="text-left py-4 px-4">Earnings</th>
              </tr>
            </thead>
            <tbody>
              {shows.map((show, idx) => (
                <motion.tr
                  key={show._id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  className="border-b border-white/5 hover:bg-white/5"
                  data-testid={`show-row-${idx}`}
                >
                  {/* <td className="py-4 px-4">
                    <div className="font-semibold">{show.movie.title}</div>
                  </td> */}
                  <td className="py-4 px-4">
                    <div className="flex items-center space-x-2 text-sm">
                      <Calendar className="h-4 w-4 text-red-500" strokeWidth={1.5} />
                      <span>{new Date(show.date).toLocaleDateString()}</span>
                      <Clock className="h-4 w-4 text-red-500 ml-2" strokeWidth={1.5} />
                      <span>{show.time}</span>
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="flex items-center">
                      <DollarSign className="h-4 w-4" strokeWidth={1.5} />
                      <span>{show.price}</span>
                    </div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="text-zinc-400">{show.bookedSeats}/{show.totalSeats}</div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="font-semibold">{show.bookingsCount}</div>
                  </td>
                  <td className="py-4 px-4">
                    <div className="font-bold text-green-500">${show.revenue.toFixed(2)}</div>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default ListShows;
